text/x-javascript","script":{"content":["// Initialize chargesAndCommissions as a list of ChargesAndCommissions
tw.local.chargesAndCommissions = new tw.object.listOf.toolkit.NBEINTT.ChargesAndCommissions();

for (var i = 0; i < tw.local.charges.listLength; i++) {
 // Initialize each item in the chargesAndCommissions array
 tw.local.chargesAndCommissions[i] = new tw.object.toolkit.NBEINTT.ChargesAndCommissions();
 
 // Initialize nested objects
 tw.local.chargesAndCommissions[i].defaultCurrency = new tw.object.toolkit.TWSYS.NameValuePair();
 tw.local.chargesAndCommissions[i].debitedAccount = new tw.object.toolkit.NBEINTT.AccountDetails2();
 tw.local.chargesAndCommissions[i].debitedAccount.accountClass = new tw.object.toolkit.TWSYS.NameValuePair();
 tw.local.chargesAndCommissions[i].debitedAccount.currency = new tw.object.toolkit.TWSYS.NameValuePair();
 tw.local.chargesAndCommissions[i].debitedAmount = new tw.object.toolkit.NBEINTT.AmountDetails();

 // Map properties from charges[i] to chargesAndCommissions[i]
 tw.local.chargesAndCommissions[i].component = tw.local.charges[i].component;
 tw.local.chargesAndCommissions[i].defaultCurrency.name = tw.local.charges[i].defaultCurrency.name;
 tw.local.chargesAndCommissions[i].defaultCurrency.value = tw.local.charges[i].defaultCurrency.value;
 tw.local.chargesAndCommissions[i].changeAmount = tw.local.charges[i].changeAmount;
 tw.local.chargesAndCommissions[i].waiver = tw.local.charges[i].waiver;
 
 tw.local.chargesAndCommissions[i].debitedAccount.accountClass.name = tw.local.charges[i].debitedAccount.accountClass.name;
 tw.local.chargesAndCommissions[i].debitedAccount.accountClass.value = tw.local.charges[i].debitedAccount.accountClass.value;
 tw.local.chargesAndCommissions[i].debitedAccount.glAccountNo = tw.local.charges[i].debitedAccount.glAccountNo;
 tw.local.chargesAndCommissions[i].debitedAccount.customerAccountNo = tw.local.charges[i].debitedAccount.customerAccountNo;
 tw.local.chargesAndCommissions[i].debitedAccount.branchCode = tw.local.charges[i].debitedAccount.branchCode;
 tw.local.chargesAndCommissions[i].debitedAccount.currency.name = tw.local.charges[i].debitedAccount.currency.name;
 tw.local.chargesAndCommissions[i].debitedAccount.currency.value = tw.local.charges[i].debitedAccount.currency.value;
 tw.local.chargesAndCommissions[i].debitedAccount.balance = tw.local.charges[i].debitedAccount.balance;
 tw.local.chargesAndCommissions[i].debitedAccount.balanceSign = tw.local.charges[i].debitedAccount.balanceSign;
 tw.local.chargesAndCommissions[i].debitedAccount.isOverDraft = tw.local.charges[i].debitedAccount.isOverDraft;

 tw.local.chargesAndCommissions[i].debitedAmount.standardExRate = tw.local.charges[i].debitedAmount.standardExRate;
 tw.local.chargesAndCommissions[i].debitedAmount.negotiatedExRate = tw.local.charges[i].debitedAmount.negotiatedExRate;
 tw.local.chargesAndCommissions[i].debitedAmount.amountInAccount = tw.local.charges[i].debitedAmount.amountInAccount;

 tw.local.chargesAndCommissions[i].rateType = tw.local.charges[i].rateType;
 tw.local.chargesAndCommissions[i].description = tw.local.charges[i].description;
 tw.local.chargesAndCommissions[i].defaultPercentage = tw.local.charges[i].defaultPercentage;
 tw.local.chargesAndCommissions[i].changePercentage = tw.local.charges[i].changePercentage;
 tw.local.chargesAndCommissions[i].defaultAmount = tw.local.charges[i].defaultAmount;
 tw.local.chargesAndCommissions[i].basicAmountCurrency = tw.local.charges[i].basicAmountCurrency;
 tw.local.chargesAndCommissions[i].flatAmount = tw.local.charges[i].flatAmount;
 tw.local.chargesAndCommissions[i].isGLFound = tw.local.charges[i].isGLFound;
 tw.local.chargesAndCommissions[i].glVerifyMSG = tw.local.charges[i].glVerifyMSG;
}

"]}},{"startQuantity":1,"outgoing":["ca197aa5-89cd-488c-8fee-9d05bbb183ce"],"extensionElements":{"nodeVisualInfo":[{"color":"#FF7782","width":95,"x":312,"y":188,"declaredType":"TNodeVisualInfo","height":69}],"activityType":["CalledProcess"]},"name":"Exception Handling","dataInputAssociation":[{"targetRef":"2055.5ea77901-7a17-422a-8958-67bb0e9c991b","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.system.serviceFlow.name"]}}]},{"targetRef":"2055.55dcd590-97c2-48df-82c6-0f812ab7177f","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.local.errorMSG"]}}]}],"isForCompensation":false,"completionQuantity":1,"declaredType":"callActivity","id":"790634bc-bade-4a4b-8074-92e74727089b","dataOutputAssociation":[{"assignment":[{"to":{"evaluatesToTypeRef":"itm.12.83ff975e-8dbc-42e5-b738-fa8bc08274a2","declaredType":"TFormalExpression","content":["tw.local.isSuccessful"]}}],"sourceRef":["2055.99eb514d-4b62-401e-8cdb-7edc096adffd"]},{"assignment":[{"to":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.local.errorMSG"]}}],"sourceRef":["2055.81b82125-a5aa-45f7-8c0f-4870667eebbf"]}],"calledElement":"1.2b50ff68-f7d3-4895-88ad-a73a13fa91d0"},{"startQuantity":1,"outgoing":["f0cde7d1-d6bc-4ff4-8049-9d4cb763e5c3"],"incoming":["1c306fcf-251b-41cf-81f5-ddbf5ac169e3"],"extensionElements":{"nodeVisualInfo":[{"color":"#FFC875","width":95,"x":517,"y":57,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Map Output","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"5aeb1d16-985b-48c3-8464-7c0ddc122f00","scriptFormat":"text/x-javascript","script":{"content":["tw.local.isClosed = false;
