}"]}},{"targetRef":"9c292ea6-df38-4ff9-8b5f-f6305a2433bc","extensionElements":{"sequenceFlowImplementation":[{"fireValidation":"Never","sboSyncEnabled":true,"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TSequenceFlowImplementation"}],"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":true,"showLabel":false}]},"name":"To Exclusive Gateway","declaredType":"sequenceFlow","id":"f0cde7d1-d6bc-4ff4-8049-9d4cb763e5c3","sourceRef":"5aeb1d16-985b-48c3-8464-7c0ddc122f00"},{"incoming":["ca197aa5-89cd-488c-8fee-9d05bbb183ce","ecc0f8a9-6ae8-4a08-8829-0a7c0ebf9db8"],"eventDefinition":[{"extensionElements":{"errorEventSettings":[{"catchAll":true,"errorCode":"","declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmwleext.TErrorEventSettings"}]},"declaredType":"errorEventDefinition","id":"815e0e41-d6c7-4552-89b0-c4bc2f327fe0","otherAttributes":{"eventImplId":"eb16d79b-e96f-4a5a-8b76-abd2b2a92d61"}}],"extensionElements":{"nodeVisualInfo":[{"width":24,"x":452,"y":211,"declaredType":"TNodeVisualInfo","height":24}]},"name":"End Event","dataInputAssociation":[{"assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.local.errorMSG"]}}]}],"declaredType":"endEvent","id":"d2a12916-6bb2-4e17-855e-6fd80cf87664"},{"targetRef":"d2a12916-6bb2-4e17-855e-6fd80cf87664","extensionElements":{"sequenceFlowImplementation":[{"fireValidation":"Never","sboSyncEnabled":true,"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TSequenceFlowImplementation"}],"endStateId":["guid:f6ffc3b64be5dfa5:4157166b:18ab80e0606:-6f83"],"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":true,"showLabel":false}]},"name":"To End Event","declaredType":"sequenceFlow",